#!/usr/bin/env bash
# Fetch official OpenEUICC Magisk module and stage priv-app + whitelist for hybrid pack.
# Source of truth: https://openeuicc.com/  (Magisk latest.zip)
set -euo pipefail
ROOT="$(cd "$(dirname "$0")" && pwd)"
URL="${OPENEUICC_MAGISK_URL:-https://openeuicc.com/magisk/latest.zip}"
WORK="${TMPDIR:-/tmp}/openeuicc-fetch-$$"
ZIP="$WORK/latest.zip"
OUT_APK_DIR="$ROOT/prebuilt/priv-app/OpenEUICC"
OUT_APK="$OUT_APK_DIR/OpenEUICC.apk"
OUT_XML="$ROOT/permissions/privapp_whitelist_im.angry.openeuicc.xml"
OUT_VER="$ROOT/prebuilt/VERSION"
OUT_META="$ROOT/magisk_meta/module.prop"

die() { echo "ERROR: $*" >&2; exit 1; }
need() { command -v "$1" >/dev/null 2>&1 || die "missing tool: $1"; }

need curl
need unzip
need sha256sum

mkdir -p "$WORK" "$OUT_APK_DIR" "$ROOT/permissions" "$ROOT/magisk_meta" "$ROOT/prebuilt"
echo "Fetching OpenEUICC Magisk module: $URL"
curl -fsSL --retry 3 --retry-delay 2 -o "$ZIP" "$URL"
ZIP_SHA=$(sha256sum "$ZIP" | awk '{print $1}')
echo "  zip sha256=$ZIP_SHA"

unzip -q -o "$ZIP" -d "$WORK/extracted"
SRC_APK="$WORK/extracted/system/system_ext/priv-app/OpenEUICC/OpenEUICC.apk"
SRC_XML="$WORK/extracted/system/system_ext/etc/permissions/privapp_whitelist_im.angry.openeuicc.xml"
SRC_PROP="$WORK/extracted/module.prop"
[[ -f "$SRC_APK" ]] || die "OpenEUICC.apk missing in Magisk zip layout"
[[ -f "$SRC_XML" ]] || die "privapp whitelist missing in Magisk zip layout"

cp -f "$SRC_APK" "$OUT_APK"
cp -f "$SRC_XML" "$OUT_XML"
[[ -f "$SRC_PROP" ]] && cp -f "$SRC_PROP" "$OUT_META"

APK_SHA=$(sha256sum "$OUT_APK" | awk '{print $1}')
APK_SIZE=$(stat -c '%s' "$OUT_APK")
VERSION="unknown"
VERSION_CODE="unknown"
if [[ -f "$OUT_META" ]]; then
  VERSION=$(grep -E '^version=' "$OUT_META" | head -1 | cut -d= -f2- || true)
  VERSION_CODE=$(grep -E '^versionCode=' "$OUT_META" | head -1 | cut -d= -f2- || true)
fi

cat >"$OUT_VER" <<EOF
# OpenEUICC prebuilt pin (generated by fetch.sh)
source_url=$URL
fetched_utc=$(date -u +%Y-%m-%dT%H:%M:%SZ)
module_version=$VERSION
module_version_code=$VERSION_CODE
magisk_zip_sha256=$ZIP_SHA
apk_path=prebuilt/priv-app/OpenEUICC/OpenEUICC.apk
apk_sha256=$APK_SHA
apk_bytes=$APK_SIZE
package=im.angry.openeuicc
install_path=/system/priv-app/OpenEUICC/OpenEUICC.apk
privapp_xml=permissions/privapp_whitelist_im.angry.openeuicc.xml
upstream=https://gitea.angry.im/PeterCxy/OpenEUICC
site=https://openeuicc.com/
note=CI Magisk debug APK; replace with gradle :app:assembleRelease for signed release builds
EOF

echo "OK OpenEUICC $VERSION ($VERSION_CODE)"
echo "  apk  $OUT_APK"
echo "  sha  $APK_SHA"
echo "  xml  $OUT_XML"
echo "  pin  $OUT_VER"

rm -rf "$WORK"
